<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('DELETE','POST');apiCsrf();$uid=apiAuth();$in=apiInput();$item=apiId($in['item_id']??0);$s=apiDb()->prepare('DELETE ci FROM cart_items ci JOIN carts c ON c.id=ci.cart_id WHERE ci.id=? AND c.user_id=?');$s->execute([$item,$uid]);if(!$s->rowCount())apiError('Item not found',404);apiResponse(['id'=>$item]);